<form method="get" class="panel-body advance-filter-grid"><input type="hidden" name="tab" value="<?= ecEscape($activeTab)?>"><div><label class="form-label">Search</label><input class="form-control" type="search" name="q" value="<?= ecEscape($search)?>" placeholder="Name, account, office or reference"></div><?php if ($fixedAdvanceType):?><input type="hidden" name="type" value="<?= ecEscape($fixedAdvanceType)?>"><?php else:?><div><label class="form-label">Category</label><select class="form-select" name="type"><option value="">All categories</option><option value="TRAVEL" <?= $type === 'TRAVEL' ? 'selected' : ''?>>Travel Advances</option><option value="INDIVIDUAL" <?= $type === 'INDIVIDUAL' ? 'selected' : ''?>>Individual Advances</option></select></div><?php endif;?><div><label class="form-label">Status</label><select class="form-select" name="status"><option value="">All statuses</option><option value="ACCOUNTED" <?= $status === 'ACCOUNTED' ? 'selected' : ''?>>Accounted</option><option value="UNACCOUNTED" <?= $status === 'UNACCOUNTED' ? 'selected' : ''?>>Unaccounted</option></select></div><div><label class="form-label">Office</label><select class="form-select" name="office_id"><option value="0">All offices</option><?php foreach ($offices as $o):?><option value="<?= (int)$o['id']?>" <?= $officeId === (int)$o['id'] ? 'selected' : ''?>><?= ecEscape($o['name'])?></option><?php endforeach;?></select></div><div><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?= ecEscape($from)?>"></div><div><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?= ecEscape($to)?>"></div><div><label class="form-label">Rows</label><select class="form-select" name="per_page"><?php foreach ([10,25,50,100,250] as $n):?><option value="<?= $n?>" <?= $per === $n ? 'selected' : ''?>><?= $n?></option><?php endforeach;?></select></div><button class="btn btn-primary"><i class="bi bi-search"></i> Apply</button><a class="btn btn-outline-secondary" href="<?= ecEscape($advancePage)?>?tab=<?= urlencode($activeTab)?>">Clear</a></form>
